def transform(grid):
    # 1. Identify the separator color
    sep_color = None
    for r in range(len(grid)):
        if len(grid[r]) > 0:
            # Check if row r is all the same color
            val = grid[r][0]
            if all(cell == val for cell in grid[r]):
                sep_color = val
                break

    if sep_color is None:
        # Fallback if separator not found (should not happen for valid task inputs)
        return grid

    # 2. Identify row separator indices
    row_sep_indices = [r for r in range(len(grid)) if all(grid[r][c] == sep_color for c in range(len(grid[r])))]

    # 3. Identify column separator indices
    col_sep_indices = sorted(set([c for c in range(len(grid[0])) if all(grid[r][c] == sep_color for r in range(len(grid)))]))

    # 4. Generate row intervals (regions between row separators)
    row_intervals = []
    curr = []
    for r in range(len(grid)):
        if r in row_sep_indices:
            if curr:
                row_intervals.append(curr)
                curr = []
        else:
            curr.append(r)
    if curr:
        row_intervals.append(curr)

    # 5. Generate column intervals (regions between column separators)
    col_intervals = []
    curr = []
    for c in range(len(grid[0])):
        if c in col_sep_indices:
            if curr:
                col_intervals.append(curr)
                curr = []
        else:
            curr.append(c)
    if curr:
        col_intervals.append(curr)

    # 6. Identify background color (from top-left region)
    bg_color = None
    if row_intervals and col_intervals:
        r_start_region = row_intervals[0]
        c_start_region = col_intervals[0]
        for r in r_start_region:
            for c in c_start_region:
                val = grid[r][c]
                if val != sep_color:
                    bg_color = val
                    break
            if bg_color:
                break

    # 7. Construct the output grid
    output = []
    for r_range in row_intervals:
        output.append([])
        for c_range in col_intervals:
            count_objects = 0
            for r in r_range:
                for c in c_range:
                    val = grid[r][c]
                    # Count pixels that are not the separator and not the background color
                    # The "object" is implicitly the other color(s) present in the region.
                    if val != sep_color and val != bg_color:
                        count_objects += 1

            # If object count is odd, the output cell takes the value of the background color.
            # If even (including 0), the output cell takes the value 1.
            # Note: Demo 1 logic showed Odd -> Bg (2), Even -> 1.
            if count_objects % 2 == 1:
                output[-1].append(bg_color)
            else:
                output[-1].append(1)

    return output
